/* ============================================================
   76° — Seventy Six Degrees · tokens.css
   The ONLY file in the system permitted to contain color literals.
   (Slop Firewall A1: any hex/rgb/hsl outside this file is a defect.)
   ============================================================ */

/* The cascade order, declared once and here because this file loads first.
   Without it the order is whatever the bundler happened to emit, and a
   product's own rules can silently lose to a component's — layer order
   beats specificity, so no amount of selector weight recovers it.
   A consuming app appends its own layer after these four. */
@layer sv-tokens, sv-base, sv-components, sv-site;

@layer sv-tokens {
  :root {
    /* neutrals — the wall & the ink */
    --sv-band:       #1B1F26;   /* ink band (header) */
    --sv-band-line:  #2C323B;   /* hairlines on band */
    --sv-band-soft:  #8A93A2;   /* soft text on band */
    --sv-wall:       #F2F3F5;   /* platinum background */
    --sv-paper:      #FFFFFF;   /* card surface — and ONLY that */
    --sv-on-dark:    #FFFFFF;   /* the mark on dark chrome or on a seed fill:
                                   band text, on-band focus ring, primary
                                   button label, checkbox/radio mark. Never
                                   overridden per mode — the band and the seed
                                   do not invert, so neither does their mark. */
    --sv-ink:        #1C2026;   /* primary text */
    --sv-ink-soft:   #667080;   /* secondary text */
    --sv-ink-faint:  #99A1AD;   /* labels, hints — never sole carrier (C2) */
    --sv-line:       #E9EBEE;   /* internal hairlines */
    --sv-field-line: #D8DCE1;   /* form field borders */
    --sv-field-line-strong: #7E8794; /* 3.63:1 on paper. For controls whose
                                   BORDER is the ONLY affordance — an empty
                                   PinField box carries no label, no value and
                                   no fill, so the hairline above would leave
                                   it at 1.38:1 and fail the 3:1 non-text bar
                                   (WCAG 1.4.11). Ordinary fields keep the
                                   hairline: their label and value identify
                                   them, the border only decorates. */
    --sv-compare:    #D6DAE0;   /* comparison series in charts — the only
                                   permitted non-token chart color, aliased */

    /* seed — Layer 3, per product (default: Cobalt / ERP) */
    --sv-seed:       #2C5BE0;
    --sv-seed-text:  #2C5BE0;   /* seed used AS text; differs when fills pass
                                   but text fails the C1 rule (see Signal) */
    --sv-seed-line:  var(--sv-seed); /* seed used AS a 1–2px LINE: focus rings,
                                   focus borders, accent rules. Splits from the
                                   fill for exactly the reason --sv-seed-text
                                   does — on dark paper the raw seed is 2.90:1
                                   and misses the 3:1 non-text bar, so a focus
                                   ring drawn in it is invisible. Tracks the
                                   seed in light; tracks --sv-seed-text in
                                   dark, where that step is already AA-verified. */
    --sv-seed-deep:  #1E44B4;   /* pressed */
    --sv-seed-tint:  #EEF3FE;   /* icon tiles, selected rows */

    /* functional — words and 6px dots ONLY (contrast-verified on paper) */
    --sv-ok:         #14804A;   /* 4.98:1 on white — AA */
    --sv-bad:        #C43D2E;   /* 5.18:1 on white — AA */
    --sv-on-bad:     #FFFFFF;   /* the mark on a --sv-bad FILL (the dialog's
                                   final confirm — the one red fill allowed).
                                   Unlike --sv-on-dark this DOES flip per mode,
                                   because --sv-bad itself brightens on dark. */

    /* scrim — Dialog only, flat, no blur */
    --sv-scrim:      rgba(27, 31, 38, 0.4);

    /* geometry & elevation */
    --sv-r:          4px;                              /* the only radius */
    --sv-shadow:     0 1px 2px rgba(16, 20, 28, 0.05); /* the only shadow */

    /* spacing scale (4px base) */
    --sv-s1: 4px;  --sv-s2: 8px;  --sv-s3: 12px; --sv-s4: 16px;
    --sv-s5: 20px; --sv-s6: 24px; --sv-s7: 32px; --sv-s8: 40px;

    /* type */
    --sv-font-ui:   'Hanken Grotesk Variable', 'Hanken Grotesk', system-ui, sans-serif;
    --sv-font-mono: 'Fragment Mono', ui-monospace, monospace;
    /* The PUBLIC surface's display face, and the third family A1 names.
       Archivo carries a WIDTH axis as well as a weight one, which is the
       whole reason it is this face and not a second static file: the same
       font sets a condensed, heavy poster title at 1440px and relaxes to a
       readable one at 320px, so the title degrades INTO the system exactly
       as --sv-display-1 does. FIREWALL RULE 20 rejects it outside the
       marketing components — a product screen never changes face. */
    --sv-font-display: 'Archivo Variable', 'Archivo', var(--sv-font-ui);

    /* display — the PUBLIC surface only (v0.5). The product ramp tops out
       at 27px (the PageHero h1), so a marketing page had no honest way to
       speak above the work. These three steps are it, and FIREWALL RULE 17
       rejects them anywhere but the registered marketing components: no
       dashboard grows a 64px number.
       They clamp rather than sit at a fixed step because a 64px line does
       not survive 320px (C7). The floor of each is the size the same line
       would take in the product ramp, so the page degrades INTO the system
       rather than out of it. */
    --sv-display-1: clamp(34px, 6.4vw, 64px);
    --sv-display-2: clamp(27px, 4.8vw, 48px);
    --sv-display-3: clamp(21px, 3.4vw, 34px);

    /* motion — opacity/color fades only, never layout (A1).
       Both collapse to 0ms under prefers-reduced-motion. */
    --sv-t-fast: 120ms;
    --sv-t:      160ms;

    /* The two POSTURE durations, declared here at the value an
       UN-DECLARED 76° page has: off. A 0ms entrance is not a broken
       entrance, it is the element already being there, and a 0ms count
       is the figure already printed. The whole argument is at the foot
       of this file, under "The moving surface". */
    --sv-t-enter: 0ms;
    --sv-t-count: 0ms;

    /* layering — the only z-index ladder (Firewall E). Non-visual.
       Native <dialog> and [popover] use the browser top layer and
       need no z-index at all — prefer them. */
    --sv-z-band:   10;   /* sticky band / topbar */
    --sv-z-sticky: 20;   /* sticky in-page (table headers) */
    --sv-z-scrim:  30;   /* dialog scrim (non-native fallback) */
    --sv-z-dialog: 40;   /* dialog (non-native fallback) */
    --sv-z-toast:  50;   /* toasts */
    --sv-z-tip:    60;   /* tooltips (non-popover fallback) */
    --sv-z-skip:   70;   /* skip link (C4) — first tab stop, wins over all */
  }

  @media (prefers-reduced-motion: reduce) {
    :root {
      --sv-t-fast: 0ms;
      --sv-t:      0ms;
    }
  }

  /* ---- Per-product seed registry (Layer 3) ------------------
     One seed per product. tint = seed at ~8% on white,
     deep = seed darkened ~20%. New seeds must pass C1:
     seed-on-white >= 4.5:1 AND white-on-seed >= 4.5:1. */

  [data-seed='cobalt'] {
    --sv-seed:      #2C5BE0;   /* ERP · 5.70:1 both ways */
    --sv-seed-text: #2C5BE0;
    --sv-seed-line: var(--sv-seed);  /* 5.71:1 on paper */
    --sv-seed-deep: #1E44B4;
    --sv-seed-tint: #EEF3FE;
  }

  [data-seed='verdigris'] {
    --sv-seed:      #12836F;   /* CRM · 5.0:1 both ways */
    --sv-seed-text: #12836F;
    --sv-seed-line: var(--sv-seed);  /* 4.66:1 on paper */
    --sv-seed-deep: #0D6152;
    --sv-seed-tint: #EAF5F2;
  }

  [data-seed='signal'] {
    --sv-seed:      #D9531E;   /* POS · fills only (white on seed 4.6:1) */
    --sv-seed-text: #C24413;   /* seed-as-text variant — passes on white */
    --sv-seed-line: var(--sv-seed);  /* 4.03:1 on paper */
    --sv-seed-deep: #A83E12;
    --sv-seed-tint: #FCF0EA;
  }
}

/* ============================================================
   Dark mode — the disciplined dark surface (v0.2.0).
   Light stays the default (light-first). Dark is opt-in via
   <html data-mode="dark"> and changes ONLY these tokens:
   the same paper-on-a-wall physics, inverted. Cards stay the
   lightest surface in view; the band stays the darkest.
   Functional + seed-as-text steps are re-verified AA on dark
   paper (#1B1F26). Nothing else may change per mode.
   ============================================================ */

@layer sv-tokens {
  :root {
    color-scheme: light;
  }

  [data-mode='dark'] {
    color-scheme: dark;

    /* neutrals — inverted ladder, paper is the LIGHTEST surface */
    --sv-band:       #0D1014;   /* chrome stays the darkest thing on screen */
    --sv-band-line:  #232932;
    --sv-band-soft:  #8A93A2;
    --sv-wall:       #121519;   /* the wall recedes */
    --sv-paper:      #1B1F26;   /* cards read as raised paper */
    --sv-ink:        #E6E9EE;   /* 13.9:1 on dark paper */
    --sv-ink-soft:   #A7AFBB;   /* 7.4:1 on dark paper — AA */
    --sv-ink-faint:  #6E7784;   /* never a sole carrier (C2), same as light */
    --sv-line:       #272D36;
    --sv-field-line: #3A414C;
    --sv-field-line-strong: #6E7784; /* 3.65:1 on dark paper */
    --sv-compare:    #3C434E;   /* comparison series on dark grids */

    /* functional — brightened to hold AA on dark paper */
    --sv-ok:         #4CC38A;   /* ≥ 4.5:1 on #1B1F26 */
    --sv-bad:        #F0705F;   /* ≥ 4.5:1 on #1B1F26 */
    --sv-on-bad:     #1B1F26;   /* 5.66:1 on the brightened fill (white is
                                   2.92:1 there). --sv-on-dark stays white. */

    /* seed-as-surface is unchanged (white-on-seed already passed C1);
       seed-as-text brightens per seed below; tint derives from the seed
       so every registered seed gets a correct dark tint for free. */
    --sv-seed-tint:  color-mix(in srgb, var(--sv-seed) 16%, var(--sv-paper));

    --sv-scrim:      rgba(0, 0, 0, 0.55);
    --sv-shadow:     0 1px 2px rgba(0, 0, 0, 0.4);
  }

  /* seed-as-LINE follows seed-as-text on dark: the raw seed is 2.90:1 on
     dark paper, so every focus ring drawn in it would fail 1.4.11/2.4.11.
     These steps are already AA as text, so they clear 3:1 as a line with
     room to spare (cobalt 6.16:1, verdigris 7.19:1, signal 7.65:1).

     Each seed is matched in TWO positions, and the second is not optional.
     A product screen declares its seed on its own wrapper — <div data-seed>
     inside the document, not on <html> — and a custom property resolves at
     the NEAREST declaration, so that wrapper's light-mode literals would
     shadow every dark step below it: the whole template would draw seed
     text at 2.90:1 and a light tint on dark paper. The descendant form
     outranks the bare [data-seed] block and restates the dark steps for the
     subtree, so a seeded region inside a dark document is exactly as
     AA-verified as a seeded document. */

  [data-mode='dark'][data-seed='cobalt'],
  [data-mode='dark'] [data-seed='cobalt'],
  [data-mode='dark']:not([data-seed]) {
    --sv-seed-text: #7C9BF2;    /* cobalt as text on dark paper — AA */
    --sv-seed-line: var(--sv-seed-text);
  }

  [data-mode='dark'][data-seed='verdigris'],
  [data-mode='dark'] [data-seed='verdigris'] {
    --sv-seed-text: #35BFA4;
    --sv-seed-line: var(--sv-seed-text);
  }

  [data-mode='dark'][data-seed='signal'],
  [data-mode='dark'] [data-seed='signal'] {
    --sv-seed-text: #F59A6B;
    --sv-seed-line: var(--sv-seed-text);
  }

  /* The tint derives from the seed, so it needs no per-seed branch — only
     the same reach past a nested wrapper's light literal. */
  [data-mode='dark'] [data-seed] {
    --sv-seed-tint: color-mix(in srgb, var(--sv-seed) 16%, var(--sv-paper));
  }
}

/* ============================================================
   The printed surface (v0.6) — paper is the third surface.

   It is declared here, in the tokens, for exactly the reason
   dark is: it changes ONLY tokens. A `print.css` was proposed
   during the 0.6 audit and REFUSED, because the dark surface's
   governing rule reads one word wider than it was written —
   "no component may branch on the mode" is "no component may
   branch on the MEDIUM". What a component knows about paper it
   learns from a token, or it does not learn it.

   Print is the LIGHT surface restated IN FULL, plus the
   amendments below — not a patch on whatever happened to be on
   screen. In full, because <html data-mode="dark"> prints too,
   and a printer emits no ink for #1B1F26: a dark document left
   un-restated prints #E6E9EE type onto a white sheet, which is
   a blank page that took ninety seconds. That is precisely the
   silent loss C7 exists to forbid, arriving through the token
   layer instead of through a scroll container.

   The second half of this surface — what the PAGE does with
   these values — is the `@media print` block in base.css.
   ============================================================ */

@layer sv-tokens {
  @media print {
    :root,
    [data-mode='dark'] {
      color-scheme: light;

      /* ---- The wall and the band ------------------------------
         A 1280px ink band prints as a solid dark rectangle across
         the head of every sheet: a page of toner, and a header
         nobody can write a note on. The band is CHROME — it states
         where you are inside an application — and a sheet of paper
         is not inside anything. It becomes paper, and states its
         own end with a rule instead of with a colour (that rule is
         base.css's, because a token cannot draw a border).
         The wall goes with it: the wall is the surface a card
         RESTS on, and the sheet is already that surface. Paper on
         paper needs an edge, not a backdrop.
         B46 `Split` falls out of this for free — its two halves
         are --sv-band and --sv-wall, so on paper the seam closes
         and the page prints as exactly the B24 Plate it composes.
         The halves carry nothing, so nothing is lost with them. */
      --sv-band:       #FFFFFF;
      --sv-wall:       #FFFFFF;
      --sv-paper:      #FFFFFF;

      /* The mark inverts here, and ONLY here. --sv-on-dark exists
         because the band and the seed do not invert per mode, so
         the mark on them must not either (v0.2.1). Both premises
         fail on paper at once: the band is no longer dark, and a
         seed fill is a BACKGROUND, which a printer drops by
         default. A white mark would print white-on-white in both
         positions — the PageHero's h1 and the primary button's
         label, gone, with nothing on the page to say so. It goes
         ink. One token, one job, restated for one medium: "the
         mark on chrome or on a seed fill", and on paper neither
         of those surfaces is there to be marked.
         The residual is named rather than hidden: a reader who
         ticks "background graphics" gets the seed fill back under
         an ink label at 2.87:1. 76° takes that over a label that
         is invisible by default — a contrast miss the reader
         opted into beats a word that is not on the page. */
      --sv-on-dark:    #1C2026;

      /* Band secondary text was verified at 5.32:1 ON INK (C1).
         On paper it is 3.10:1 and fails, so it takes --sv-ink-
         soft's step, which is verified at 4.99:1. This is the
         context line, the wordmark's degree mark and every
         inactive nav item. */
      --sv-band-soft:  #667080;

      /* ---- Hairlines, sized for toner rather than for a panel --
         #E9EBEE is ~9% ink. A 1px rule at 9% renders as a sparse
         dither on a 300dpi laser and is gone after one photocopy.
         On paper the hairline is doing MORE work than on screen,
         not less: there is no hover, no focus and no elevation
         left, so the rule is the only thing separating two table
         rows, ruling a `<dl>` pair, or closing a card. ~21% is the
         conventional print hairline and it is what these become. */
      --sv-line:       #C9CED5;
      --sv-band-line:  #C9CED5;

      /* On paper a field's border is its sole affordance BY
         DEFINITION — nothing focuses it, nothing types into it, no
         caret identifies it, and a printed form is a form somebody
         fills in by hand. So the ordinary field line takes the
         strong step (3.63:1), which is B25's reasoning for an
         empty PinField box arriving one surface later. */
      --sv-field-line: #7E8794;
      --sv-field-line-strong: #7E8794;

      /* The light ink ladder, restated: the dark ladder is a
         screen ladder and prints as almost nothing. */
      --sv-ink:        #1C2026;   /* 15.7:1 on paper */
      --sv-ink-soft:   #667080;   /* 4.99:1 — AA */
      --sv-ink-faint:  #99A1AD;   /* unchanged. C2 already forbids it
                                     carrying anything alone, so a step
                                     that photocopies away costs the
                                     reader nothing it was ever
                                     permitted to hold. */
      --sv-ok:         #14804A;   /* 4.98:1 on paper — AA */
      --sv-bad:        #C43D2E;   /* 5.18:1 on paper — AA */

      /* --sv-on-bad flips for the same reason --sv-on-dark does,
         and it is the token that always said it would: its one
         legal position is a mark on a red FILL, and a fill on
         paper is no fill at all. */
      --sv-on-bad:     #1C2026;

      /* A 2px comparison line at 1.28:1 is not a faint line on
         paper, it is an absent one — and B5 draws the comparison
         series as a STROKE, which is ink rather than background,
         so it prints whatever the reader chose. It takes the faint
         step: still visibly the second series beside a seed line,
         now actually on the page. */
      --sv-compare:    #99A1AD;

      /* ---- The seed -------------------------------------------
         The seed is UNCHANGED and needs no printed variant. It
         survives a colour printer and flattens to a mid grey on a
         mono one — and C5 has already paid for that in advance:
         no 76° meaning is carried by colour. A status is a word
         beside a dot, a delta is an arrow glyph, an active tab is
         weight plus aria-current, a chart series is labelled in
         its legend. Greyscale strips decoration off a 76° page and
         takes no information with it. That is the entire argument
         for the printed surface being a token change.

         --sv-seed-tint is the one place that stops being true, and
         it is worth naming as the exception rather than trusting
         the rule. It is not a mark, it is a FILL — the fill B7 and
         B40 put under a SELECTED row. A printer either drops it or
         renders it as a pale grey band that reads as a smudge, and
         a photocopier amplifies it into one. Its other cue is the
         2px seed LEFT RULE that B7 registered as the only left
         rule in the system: a shape, not a shade, and a shape
         prints in every mode on every printer. The rule states
         the selection; the tint goes to paper, and the toner it
         would have spent on 200 hover-coloured rows stays in the
         cartridge. */
      --sv-seed-tint:  #FFFFFF;

      /* ---- Layers that cannot print ---------------------------
         A scrim dims what is BEHIND a dialog. Paper has no
         behind, so the token has no job and takes no ink. */
      --sv-scrim:      transparent;

      /* Elevation is a claim about light that a lit screen can
         make and a sheet cannot; a printer renders --sv-shadow as
         a grey smear along two edges of every card. A4's "every
         card: zero border" is a SCREEN rule, and its reason is
         that the shadow already draws the edge — with the shadow
         gone the card has no edge at all. So on paper it takes a
         hairline. A token cannot add a border, so that ONE rule
         lives in base.css with the rest of the printed page, and
         never in card.css, which must not know what medium it is
         being read on. */
      --sv-shadow:     none;

      /* Motion cannot print. The printed surface takes the same
         0ms the reduced-motion surface takes, for the same
         reason: 76° loses nothing, by design. */
      --sv-t-fast:     0ms;
      --sv-t:          0ms;
    }

    /* The tint is matched in the DESCENDANT position too, for the
       reason the v0.4.0 dark amendment states in full: a product
       declares its seed on its own wrapper, a custom property
       resolves at the NEAREST declaration, and that wrapper's own
       literal would otherwise shadow the step above it — printing
       a pale blue band under every selected row of a document that
       had asked for none. A seeded region on a printed page is
       exactly as considered as a printed document. */
    [data-seed],
    [data-mode='dark'] [data-seed] {
      --sv-seed-tint: #FFFFFF;
    }

    /* A dark document restores the LIGHT seed-as-text and
       seed-as-line steps: #7C9BF2 is AA on dark paper and 2.4:1 on
       a white sheet, so every link, active tab and focus ring in a
       printed dark document would be a pale smudge. Three seeds,
       both positions, mirroring the dark block above line for
       line — for the same reason it needs both. */
    [data-mode='dark'][data-seed='cobalt'],
    [data-mode='dark'] [data-seed='cobalt'],
    [data-mode='dark']:not([data-seed]) {
      --sv-seed-text: #2C5BE0;    /* 5.70:1 on paper */
      --sv-seed-line: var(--sv-seed);
    }

    [data-mode='dark'][data-seed='verdigris'],
    [data-mode='dark'] [data-seed='verdigris'] {
      --sv-seed-text: #12836F;    /* 5.0:1 on paper */
      --sv-seed-line: var(--sv-seed);
    }

    [data-mode='dark'][data-seed='signal'],
    [data-mode='dark'] [data-seed='signal'] {
      --sv-seed-text: #C24413;    /* the seed-as-text variant — the raw
                                     #D9531E is 4.0:1 on white and fails */
      --sv-seed-line: var(--sv-seed);
    }
  }
}

/* ============================================================
   The moving surface (v0.6.1) — motion is the fourth surface.

   It is declared here, in the tokens, for exactly the reason
   dark and print are: it changes ONLY tokens, and no component
   may branch on it. A `motion.css` would be an invitation for a
   component to reach into it and start performing.

   THE GOVERNING PRINCIPLE, and the test every addition to this
   surface has to pass: MOTION NEVER CARRIES INFORMATION. Every
   figure a count-up animates to is already printed — in the
   accessible name, in the visually-hidden line beside it, in the
   DOM at first paint. Delete the animation and the screen still
   states everything it stated. That is B44's own test arriving
   one surface later ("delete the strip and the card still
   answers the question"), and it is why C7 can send this entire
   surface to 0ms and lose nothing, by design.

   OFF IS THE DEFAULT. A 76° page that says nothing moves
   nothing: `--sv-t-enter` and `--sv-t-count` are 0ms at :root,
   and only a wrapper that DECLARES `data-motion='on'` turns them
   into durations. This is the dark surface's posture verbatim —
   registered, opt-in, resolved at the nearest declaration — and
   it is the opposite of the usual arrangement, where motion is
   what a library does until somebody asks it to stop.

   A2 bans the skeleton shimmer and, in spirit, anything that
   performs; nothing here performs. There are exactly two moves:
   an element ARRIVES (opacity and a 6px transform, base.css),
   and a figure COUNTS to a number it is already printing. The
   system still has exactly one continuous animation, `sv-rotate`,
   and this surface does not add a second.
   ============================================================ */

@layer sv-tokens {
  /* ---- A1 · the 200ms ceiling, argued rather than dodged ----

     A1 bans "`animation` durations > 200ms". Two tokens land on
     that rule and they land on different sides of it, so both
     decisions are written down.

     `--sv-t-enter` is 200ms: AT the ceiling, not over it, and no
     amendment is claimed. The ceiling is not a budget, it is a
     definition — past 200ms a reader stops perceiving an
     interface that has arrived and starts perceiving one that is
     arriving. 200ms is enough here because the entrance has
     almost no distance to cover: one opacity step and six pixels.
     A longer entrance would not be a better entrance, it would be
     a slower page, and the page has nothing to say while it runs.
     It is the longest duration in the system and the only one
     that is not feedback on an act the reader performed.

     `--sv-t-count` is 640ms and IS AN AMENDMENT TO A1's 200ms
     ceiling, registered here, fenced to this one token, and
     stated rather than smuggled. Two things could have hidden it
     and neither is honest: it is not a CSS `animation` (no
     keyframe runs, so the firewall's grep never sees it), and it
     is a JS constant's default (so it need never have appeared in
     a stylesheet at all). Both are true and neither is a reason.

     The reason the ceiling does not bind is the principle above.
     A1's ceiling protects a reader who is WAITING — on a panel, a
     state change, a control's answer. A count-up is not something
     anyone waits on: the figure is in the accessible name and in
     a visually-hidden line at first paint, so the information has
     already landed and the count is the only thing still moving.
     And a six-digit figure counted in 200ms is not a count, it is
     a flicker — it spends the same attention and returns none of
     the legibility, which makes "a count-up short enough for A1"
     the one option that is both slow and useless. So the choice
     was a count long enough to read as one, or no count at all.
     640ms is four times the system step (--sv-t, 160ms), which is
     where the number comes from: it is not a new tempo, it is the
     existing one, four beats long.

     The amendment is fenced three ways and it is the fencing that
     makes it survivable: it is 0ms unless a wrapper declares the
     posture, 0ms under prefers-reduced-motion whatever anyone
     declared, and 0ms on paper. */

  [data-motion='on'] {
    --sv-t-enter: 200ms;
    --sv-t-count: 640ms;
  }

  /* ---- C7 · reduced motion wins, at every depth ------------
     "All transitions → 0ms; 76° loses nothing, by design." The
     collapse names the ATTRIBUTE and not only `:root`, and that
     is the v0.4.0 seed amendment's finding arriving in the motion
     layer. A custom property resolves at the NEAREST declaration,
     and `[data-motion='on']` is declared on a WRAPPER inside the
     document rather than on <html> — so a `:root`-only collapse
     would be shadowed by that wrapper's own 640ms for its whole
     subtree, and the one region a user asked to hold still would
     be the region that moved. The bare attribute selector reaches
     the same-element position (<html data-motion='on'>) and the
     descendant one (any wrapper below it) in a single form,
     because — unlike the seed's compound
     `[data-mode='dark'][data-seed]`, which had to be restated as
     a descendant — there is nothing to compound it with. It also
     matches `data-motion='off'`, which is the point: a nested
     posture that turns motion OFF must be able to beat the `on`
     above it, and it resolves at its own nearest declaration too.

     Source order carries this: `[data-motion]` and
     `[data-motion='on']` are the same specificity, so the
     collapse must sit after the declaration it corrects. That is
     why this whole surface is one block at the foot of the file
     rather than a pair of lines added to the two blocks above. */
  @media (prefers-reduced-motion: reduce) {
    :root,
    [data-motion] {
      --sv-t-enter: 0ms;
      --sv-t-count: 0ms;
    }
  }

  /* Motion cannot print — the printed surface takes the same 0ms
     for the same reason it takes it for --sv-t-fast and --sv-t.
     Stated here rather than in the print block above because that
     block matches `:root, [data-mode='dark']`, and a posture
     wrapper is neither. */
  @media print {
    :root,
    [data-motion] {
      --sv-t-enter: 0ms;
      --sv-t-count: 0ms;
    }
  }
}

/* ============================================================
   76° · base.css — reset, typography defaults, focus contract
   ============================================================ */

@layer sv-base {
  *,
  *::before,
  *::after {
    box-sizing: border-box;
  }

  html {
    -webkit-text-size-adjust: 100%;
  }

  body {
    margin: 0;
    background: var(--sv-wall);
    color: var(--sv-ink);
    font-family: var(--sv-font-ui);
    font-size: 13px;
    line-height: 1.5;
    font-weight: 500;
    -webkit-font-smoothing: antialiased;
  }

  h1, h2, h3, h4, p, figure, blockquote, dl, dd {
    margin: 0;
  }

  img, svg {
    display: block;
    max-width: 100%;
  }

  button, input, select, textarea {
    font: inherit;
    color: inherit;
  }

  /* C3 · Focus — every interactive element, no exceptions */
  :focus-visible {
    outline: 2px solid var(--sv-seed-line);
    outline-offset: 2px;
  }

  /* On the band, focus is white for contrast — in both modes */
  .sv-band :focus-visible {
    outline-color: var(--sv-on-dark);
  }

  /* A4 · numbers that can change are tabular, always */
  .sv-num {
    font-variant-numeric: tabular-nums;
  }

  /* Mono metadata voice (Law 4) */
  .sv-mono {
    font-family: var(--sv-font-mono);
    font-size: 10px;
    font-weight: 400;
    letter-spacing: 0.13em;
    text-transform: uppercase;
  }

  /* C4 · Skip link — first tab stop, visible on focus over the band */
  .sv-skip {
    position: absolute;
    left: var(--sv-s4);
    top: var(--sv-s2);
    z-index: var(--sv-z-skip);
    padding: var(--sv-s2) var(--sv-s4);
    background: var(--sv-paper);
    color: var(--sv-ink);
    border-radius: var(--sv-r);
    box-shadow: var(--sv-shadow);
    font-size: 12px;
    font-weight: 600;
    text-decoration: none;
    transform: translateY(-200%);
  }

  .sv-skip:focus-visible {
    transform: none;
  }

  /* Visually hidden, screen-reader available */
  .sv-visually-hidden {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
    border: 0;
  }

  /* C7 · reduced motion — handled at the token layer: every transition
     in the system uses var(--sv-t) / var(--sv-t-fast), which collapse
     to 0ms under prefers-reduced-motion (see tokens.css). 76° loses
     nothing, by design. */

  /* ============================================================
     The moving surface (v0.6.1) — what the PAGE does with the
     posture. `tokens.css` states what the two motion tokens
     BECOME when a wrapper declares `data-motion='on'`; these two
     rules are the whole of what uses them HERE.

     The posture is NOT the mode or the medium, and the difference
     is worth stating so nobody quotes the wrong rule at it. A
     component may never branch on the mode or the medium because
     dark and print change what a mark IS — the same paint, on a
     different surface — so a branch there means two truths. The
     posture changes only whether something MOVES on its way to a
     state it would have reached anyway, so a component may gate a
     transition of its own on it. B5 `Trend` does exactly that for
     its draw-in, because a line's stroke cannot be expressed
     through a generic entrance class. What no component may do is
     read the posture to decide what it SAYS.

     MOTION NEVER CARRIES INFORMATION. Delete either rule and the
     page states everything it stated before — a scroll still
     arrives, an element is still there.
     ============================================================ */

  /* Smooth scrolling is a property of the SCROLLING ELEMENT, so it is
     matched in the same-element position only: declared on
     <html data-motion='on'> it covers in-page anchors and every
     `scrollIntoView` in the document, and a nested scroll container
     that wants it declares the posture on itself. A posture wrapper
     that is not a scroller has nothing to smooth.

     The docs shell's route-change `window.scrollTo` deliberately
     passes `behavior: 'instant'` and keeps passing it: an explicit
     behavior overrides `scroll-behavior`, which is the intent. Going
     to the top of a page you just navigated to is not a transition
     the reader asked for — it is the browser's own behaviour on a
     multi-page site, restated by a hash-routed SPA. A 900px smooth
     scroll on every route change is the page performing.

     A duration token cannot express this one — the browser owns the
     easing and the length — so it is gated on the media query
     directly. Under `reduce` the declaration is never made, which is
     the same 0ms the tokens take, spelled the only way this property
     can spell it. */
  @media (prefers-reduced-motion: no-preference) {
    [data-motion='on'] {
      scroll-behavior: smooth;
    }
  }

  /* The entrance — the one reusable move on the surface, and INERT
     unless the posture is declared: with no `[data-motion='on']`
     above it, `.sv-enter` carries no animation at all, not a
     0ms one.

     Matched in BOTH positions for the reason the v0.4.0 seed
     amendment gives about nearest declarations: the posture is
     declared on a WRAPPER, and that wrapper is sometimes the element
     entering and sometimes the element containing it. A descendant
     selector alone would leave a section that declares its own
     posture and animates itself unstyled — the one element that
     asked for the entrance.

     Transform and opacity ONLY. A1 forbids transitioning layout
     (width/height/top/left/margin/padding), and a transform is not
     layout: it moves paint, not the box, so nothing around it
     reflows and no other element is asked to move. `both` holds the
     opening frame before the first paint and the closing one after,
     so the element never flashes at full opacity first.

     ONE keyframe. The system has exactly one continuous animation
     (`sv-rotate`, B31) and this is not a second: it runs once, it
     does not loop, and it ends. 6px, because the move has to be
     legible as an arrival and not as travel — B21's drawer slides
     24px because it comes from off-screen; this comes from where it
     already is.

     The easing decelerates and never overshoots: y stays in [0,1]
     (Ship Gate 13 / Part E). It is ease-out-cubic, the same curve
     `count-up.ts` runs in JS, so the two moves on this surface are
     one move at two layers. */
  [data-motion='on'] .sv-enter,
  [data-motion='on'].sv-enter {
    animation: sv-enter var(--sv-t-enter) cubic-bezier(0.215, 0.61, 0.355, 1) both;
  }

  @keyframes sv-enter {
    from {
      opacity: 0;
      transform: translateY(6px);
    }

    to {
      opacity: 1;
      transform: translateY(0);
    }
  }
}

/* ============================================================
   76° · the printed page (v0.6) — the second half of the
   printed surface. `tokens.css` states what every 76° token
   BECOMES on paper; this states what the page does with them.
   Both live in these two files rather than in a `print.css`,
   which was proposed during the 0.6 audit and refused: the dark
   surface's rule reads one word wider than it was written, and
   NO COMPONENT MAY BRANCH ON THE MEDIUM. Every selector below
   names a component, and not one component file knows it.

   This block is deliberately UNLAYERED, and it is the only
   unlayered CSS in the system. The order declared at the top of
   tokens.css is sv-tokens, sv-base, sv-components, sv-site — so
   a rule written into sv-base LOSES to the component rule it is
   correcting, whatever selector it carries: layer order beats
   specificity, which is the reason that line exists. The C7
   answer below has to beat `.sv-table__scroll { overflow-x:
   auto }` in sv-components, and the importance flag A1 bans is
   not available. Unlayered is the one position left, and it is
   the honest one: the printed page is not a layer stacked on
   the screen, it REPLACES the screen for one medium. A product
   overriding any of this writes its own unlayered @media print
   rule and wins on source order, exactly as it would here.
   ============================================================ */

@media print {
  /* @page is a page context, not an element context — a cascade
     layer has nothing to order it against. No `size` is set:
     A4 or Letter is the reader's paper and the printer's
     business, and a system that picks one is wrong in half the
     world. 14mm is the narrowest side gutter that a two-hole
     punch and a staple both clear, which is what happens to a
     purchase order within a minute of printing. The band's 40px
     is a screen measure and is not a page margin. */
  @page {
    margin: 16mm 14mm;
  }

  /* 76° does NOT ask the browser to honour its backgrounds, and
     it states that here rather than inheriting it silently.
     `exact` would print the wall on every page, a tint under
     every selected row and a seed rectangle behind every primary
     button — square decimetres of toner spent reproducing
     decisions the page does not need to carry, because C5
     already guarantees that nothing 76° MEANS is carried by a
     colour. Two components prove it rather than assert it: B44
     `DistributionStrip` is specified to pass the test "delete
     the strip and the card still answers the question", because
     its legend repeats every figure as text; B4 and B6 require
     the absolute numbers beside every bar and call the bar
     illustration. Economy printing removes exactly the
     illustration. Ink is spent on marks — type, rules, strokes,
     dots — and marks are where the information already lives. */
  :root {
    -webkit-print-color-adjust: economy;
    print-color-adjust: economy;
  }

  /* ---- Chrome that is not information ---------------------
     Nothing hidden here CARRIES anything. Each is either a
     control whose result the page already states, or a
     statement about a moment that ended before the sheet left
     the printer. Nothing that holds information is hidden. */

  /* C4's skip link is a keyboard affordance and its whole
     definition is "first tab stop". Paper has no tab order. */
  .sv-skip {
    display: none;
  }

  /* The top layer does not paginate: a panel left open prints
     over page one and can take the rest of the document with
     it. Every 76° top-layer surface is SPECIFIED as
     supplementary or as a list of verbs — B18 Tooltip is a
     phrase, B20 Menu is verbs, B42 Popover is a few controls —
     and C4 forbids any of them being the only path to
     anything. None of them holds something the sheet does not.
     An OPEN <dialog> is deliberately NOT hidden: B13 interrupts
     for one decision and B21 Drawer opens a workspace beside
     the work, so a reader printing with a Drawer open is
     printing the record inside it. Hiding that would be the
     silent loss the rest of this block exists to prevent. */
  [popover],
  dialog:not([open]) {
    display: none;
  }

  /* B14: a toast auto-dismisses and is never the only path to
     an action. It is a statement about a moment, and the moment
     is over. */
  .sv-toaster {
    display: none;
  }

  /* B17: a skeleton states that data has NOT ARRIVED. On paper
     there is nothing left to wait for, and a column of grey
     blocks is a page that says nothing while looking like it
     says something. */
  .sv-skeleton {
    display: none;
  }

  /* B31: the spinner is the system's one continuous animation,
     and a frozen arc states nothing at all. The Busy SENTENCE
     stays — it is required copy naming what is loading, and a
     sentence is information. The content it was dimming comes
     back to full ink: B31's own words are that it "is still
     true until it changes", and 40% ink is a photocopy of
     nothing. The overlay is un-positioned with it, or the
     sentence prints on top of the rows it was covering. */
  .sv-spin {
    display: none;
  }

  .sv-busy--over .sv-busy__line {
    position: static;
  }

  .sv-busy--over > :not(.sv-busy__line) {
    opacity: 1;
  }

  /* ---- The band, ended with a rule ------------------------
     tokens.css turned the band into paper; a surface that no
     longer differs from the sheet has to say where it stops.
     The topbar and sub-tab rows already draw --sv-band-line,
     which is now an ordinary printed hairline, so they rule
     themselves. The PageHero is the last row and carries none,
     so the band states its own bottom edge. */
  .sv-band {
    border-bottom: 1px solid var(--sv-line);
  }

  /* B2's overlap is the one place in 76° where paper crosses a
     surface boundary — B46 `Split` names it as the move it
     finishes. It exists because the band is ink and the wall is
     platinum and the card straddles both. On paper there is one
     surface and nothing to straddle, and a -44px row would
     instead cut straight through the rule directly above it.
     The signature is a property of the screen. What is left on
     paper is the ordinary gutter, and the hero's 68px of
     clearance closes with it. */
  .sv-row[data-overlap] {
    margin-top: 14px;
  }

  .sv-band__hero {
    padding-bottom: var(--sv-s6);
  }

  /* ---- C7 · a scroll region on paper ----------------------
     "Tables scroll, never truncate silently." A sheet has no
     scrollbar, so on paper the first half of that promise is
     simply unavailable and the second half is the whole of it.

     `overflow: hidden` is the failure C7 names by name: the
     columns past the container edge are gone, the table stops
     at a clean padding edge inside the card, and NOTHING on the
     page says a column was dropped. It is a firewall defect for
     the same reason.

     `overflow: visible` alone is not the answer either, and
     this is the part worth writing down: a printer does not
     paginate sideways. A 1600px table on an 800px page still
     loses its right-hand columns — it loses them at the paper's
     edge instead of at the card's.

     So the rule is `visible`, and the reason it works is what
     it releases: freed from a fixed-width scroll box, a table
     lays out at its preferred width and then shrinks toward its
     MINIMUM CONTENT width by wrapping its cells. Pages grow
     downward for free. A printed 76° table gets taller, and it
     keeps every column it was promised.

     Where a table genuinely cannot fit even fully wrapped, 76°
     chooses the table that RUNS OFF THE PAPER over the table
     that stops neatly early. Both lose the same columns; only
     one tells the reader. A column cut through mid-glyph at the
     sheet's edge is unmistakably incomplete, while a table
     clipped inside a card looks exactly like a table that
     ended. C7 forbids the silent truncation, not the visible
     one — and between an honest failure and a tidy one, a
     management system prints the honest one. */
  .sv-table__scroll,
  .sv-code__pre,
  .sv-prose pre {
    overflow: visible;
  }

  /* The only two sticky elements in the system, and both are
     scroll affordances for a scroll that no longer exists: B7's
     held identity column and B43's line gutter. Left sticky
     inside a now-`visible` ancestor they pin themselves against
     the page instead and print over the very columns they were
     holding open. */
  .sv-table__cell--held,
  .sv-code__gutter {
    position: static;
  }

  /* ---- Page-break discipline ------------------------------
     `break-inside: avoid` is a PREFERENCE, not a guarantee: a
     card taller than a page still breaks, because the
     alternative is losing it. That is the correct behaviour and
     it is why the thead note below matters. */
  .sv-card {
    break-inside: avoid;

    /* A4's "every card: zero border" is a SCREEN rule, and its
       reason is elevation: --sv-shadow already draws the edge.
       The shadow is `none` on paper (tokens.css), so with it
       gone the card has no edge at all — paper on paper. A
       hairline is what a card is without its elevation, and
       this is the one rule the token layer could not carry. */
    border: 1px solid var(--sv-line);
  }

  /* A row split across a page break is two half-rows and no
     record. */
  tr {
    break-inside: avoid;
  }

  /* There is no rule here for <thead>, and that is the finding
     rather than an omission: a browser ALREADY repeats a table
     header group on every page a table breaks across. It is
     table layout, not something CSS asks for. What CSS has to
     do is avoid DEFEATING it — a sticky or absolutely
     positioned header suppresses the repeat — and the sticky
     rule above is the whole of that. Unobstructed, the promise
     keeps itself.

     A heading that lands as the last line on a page is a title
     for a blank space. `break-after` binds it to what it
     introduces; `break-inside` keeps a two-line heading whole. */
  h1,
  h2,
  h3,
  h4 {
    break-after: avoid;
    break-inside: avoid;
  }

  /* B45 Prose is running copy, and running copy is where a page
     break strands a single line of a paragraph at the top or
     bottom of a sheet. Three lines is the typographic floor. */
  p,
  blockquote,
  li {
    orphans: 3;
    widows: 3;
  }

  /* ---- Link destinations, in one place only ---------------
     `a[href]::after { content: attr(href) }` on the document is
     the standard print snippet, and it is wrong for this
     system. 76° prints an APPLICATION: nearly every anchor on a
     76° page is a control — a band nav item, an ID cell, a text
     link action — whose href is an in-app route. Printing
     "(#/orders/PO-2291)" after every identity cell in a 200-row
     table adds a second string to the narrowest column on the
     page and pushes out the columns C7 has just fought to keep.
     It is noise, and it is noise that costs information.

     Inside B45 Prose it is the exact opposite. Prose sets
     running copy 76° did not author — a changelog, a policy, a
     help article — where a link sits inside a SENTENCE and its
     destination IS the information ("see the token reference").
     On paper that destination is lost with nothing left to
     recover it from. So the URL prints there, and only there.

     Absolute http(s) only: a same-page anchor or a hash route
     states nothing a reader holding the sheet can act on. And
     it breaks anywhere, because a 90-character URL that cannot
     break is a horizontal overflow on a 66ch measure — C7
     again, arriving through a footnote. */
  .sv-prose a[href^='http']::after {
    content: ' (' attr(href) ')';
    font-family: var(--sv-font-mono);
    font-size: 0.85em;
    color: var(--sv-ink-soft);
    word-break: break-all;
  }
}

/** Minimal class combiner. No dependency needed. */
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(' ');
}
